/**
 * @file ZW_linger.h
 * @copyright 2026 Silicon Laboratories Inc.
 *
 * @brief Application interface for the linger period.
 */
#ifndef _ZW_LINGER_H_
#define _ZW_LINGER_H_

/**
 * @brief Callback invoked when the linger period expires.
 *
 * The callback can be used by a feature such as the Wake Up Command Class to
 * resume its normal sleep/wake scheduling.
 */
typedef void (*ZW_LingerCallback_t)(void);

/**
 * @brief Register the callback invoked when the linger period expires.
 *
 * Passing NULL unregisters the current callback.
 *
 * @param[in] callback Callback to register, or NULL.
 */
void ZW_LingerSetCallback(ZW_LingerCallback_t callback);

/**
 * @brief End the active linger period.
 *
 * No expiration callback is generated by this function.
 */
void ZW_LingerRevoke(void);

#endif /* _ZW_LINGER_H_ */
